#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string N;
    if (!(cin >> N)) return 0;

    int M;
    cin >> M;

    int digitOf[256] = {0};
    string groups[10] = {
        "", "", "abc", "def", "ghi", "jkl",
        "mno", "pqrs", "tuv", "wxyz"
    };

    for (int d = 2; d <= 9; ++d) {
        for (char c : groups[d]) {
            digitOf[(unsigned char)c] = d;
        }
    }

    int answer = 0;

    while (M--) {
        string s;
        cin >> s;

        if (s.size() != N.size()) continue;

        bool ok = true;
        for (size_t i = 0; i < s.size(); ++i) {
            if (digitOf[(unsigned char)s[i]] != N[i] - '0') {
                ok = false;
                break;
            }
        }

        if (ok) ++answer;
    }

    cout << answer << '\n';
    return 0;
}
